impl Document {
    pub(crate) fn compare_application_array_data_type(
        &self,
        other: &Document,
        a: &ApplicationArrayDataType,
        b: &ApplicationArrayDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_composite_data_type(other, a.base(), b.base(), path)?;
        if a.get_dynamic_array_size_profile() != b.get_dynamic_array_size_profile() {
            return Err(format!("{path}: DYNAMIC_ARRAY_SIZE_PROFILE mismatch"));
        }
        if a.get_element() != b.get_element() {
            return Err(format!("{path}: ELEMENT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_application_composite_data_type(
        &self,
        other: &Document,
        a: &ApplicationCompositeDataType,
        b: &ApplicationCompositeDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_data_type(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_application_data_type(
        &self,
        other: &Document,
        a: &ApplicationDataType,
        b: &ApplicationDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_autosar_data_type(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_application_primitive_data_type(
        &self,
        other: &Document,
        a: &ApplicationPrimitiveDataType,
        b: &ApplicationPrimitiveDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_data_type(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_application_record_data_type(
        &self,
        other: &Document,
        a: &ApplicationRecordDataType,
        b: &ApplicationRecordDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_composite_data_type(other, a.base(), b.base(), path)?;
        let list_a = a.get_record_elements();
        let list_b = b.get_record_elements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RECORD_ELEMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.application_record_elements.get(*x).ok_or_else(|| {
                format!("{path}.RECORD_ELEMENTS[{index}]: id not found in own arena")
            })?;
            let y = other.application_record_elements.get(*y).ok_or_else(|| {
                format!("{path}.RECORD_ELEMENTS[{index}]: id not found in other arena")
            })?;
            self.compare_application_record_element(
                other,
                x,
                y,
                &format!("{path}.RECORD_ELEMENTS[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_autosar_data_type(
        &self,
        other: &Document,
        a: &AutosarDataType,
        b: &AutosarDataType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        if a.get_sw_data_def_props() != b.get_sw_data_def_props() {
            return Err(format!("{path}: SW_DATA_DEF_PROPS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_data_type_map(
        &self,
        _other: &Document,
        a: &DataTypeMap,
        b: &DataTypeMap,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_application_data_type_ref() != b.get_application_data_type_ref() {
            return Err(format!("{path}: APPLICATION_DATA_TYPE_REF mismatch"));
        }
        if a.get_implementation_data_type_ref() != b.get_implementation_data_type_ref() {
            return Err(format!("{path}: IMPLEMENTATION_DATA_TYPE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_data_type_mapping_set(
        &self,
        other: &Document,
        a: &DataTypeMappingSet,
        b: &DataTypeMappingSet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_blueprintable(other, a.base(), b.base(), path)?;
        let list_a = a.get_data_type_maps();
        let list_b = b.get_data_type_maps();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DATA_TYPE_MAPS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.data_type_maps.get(*x).ok_or_else(|| {
                format!("{path}.DATA_TYPE_MAPS[{index}]: id not found in own arena")
            })?;
            let y = other.data_type_maps.get(*y).ok_or_else(|| {
                format!("{path}.DATA_TYPE_MAPS[{index}]: id not found in other arena")
            })?;
            self.compare_data_type_map(other, x, y, &format!("{path}.DATA_TYPE_MAPS[{index}]"))?;
        }
        let list_a = a.get_mode_request_type_maps();
        let list_b = b.get_mode_request_type_maps();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODE_REQUEST_TYPE_MAPS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.mode_request_type_maps.get(*x).ok_or_else(|| {
                format!("{path}.MODE_REQUEST_TYPE_MAPS[{index}]: id not found in own arena")
            })?;
            let y = other.mode_request_type_maps.get(*y).ok_or_else(|| {
                format!("{path}.MODE_REQUEST_TYPE_MAPS[{index}]: id not found in other arena")
            })?;
            self.compare_mode_request_type_map(
                other,
                x,
                y,
                &format!("{path}.MODE_REQUEST_TYPE_MAPS[{index}]"),
            )?;
        }
        Ok(())
    }
}
